    uint16_t result;
    /* TODO END 2 */
};

div_8bitInTx in_tx_ref;
div_8bitOutTx out_tx_ref;

class div_8bitScb
{
private:
    std::deque<div_8bitInTx *> in_q;

public:
    // Input interface monitor port
    void writeIn(div_8bitInTx *tx)
    {
        // Push the received transaction item into a queue for later
        in_q.push_back(tx);
    }

    // Output interface monitor port
    void writeOut(div_8bitOutTx *tx)
    {
        // We should never get any data from the output interface
        // before an input gets driven to the input interface
        if (in_q.empty())
        {
            std::cout << "Fatal Error in div_8bitScb: empty div_8bitInTx queue" << std::endl;
            exit(1);
        }

        // Grab the transaction item from the front of the input item queue
        div_8bitInTx *in;
        in = in_q.front();
        in_q.pop_front();

        /* TODO BEGIN 3 */
        if (in->rst)
        {
            if (!(tx->res_valid == 0 && tx->result == 0))
            {
                printf("\r\n# TODO 3 Failed at simtime %ld", sim_time);
                printf("\r\n# TODO 3 INPUT TRACE: in->dividend = 0x%x, in->divisor = 0x%x, in->opn_valid = 0x%x, in->res_ready = 0x%x, in->sign = 0x%x", in->dividend, in->divisor, in->opn_valid, in->res_ready, in->sign);
                printf("\r\n# TODO 3 OUTPUT TRACE: tx->res_valid = 0x%x, tx->result = 0x%x", tx->res_valid, tx->result);

                printf("\r\n");
                fflush(stdout);

                myexit(tx->res_valid == 0 && tx->result == 0, "TODO 3 Failed: Reset logic result of the Verilog module is incorrect")
            }
        }
        else if (tx_data_gen_time == 3)
        {
            // calculation
            uint8_t quotient, remainer;
            if (in->sign)
            {
                quotient = (int8_t)in->dividend / (int8_t)in->divisor;
                remainer = (int8_t)in->dividend - (int8_t)quotient * (int8_t)in->divisor;
            }
            else
            {
                quotient = in->dividend / in->divisor;
                remainer = in->dividend - quotient * in->divisor;
            }
            uint16_t result = quotient | (remainer << 8);

            if (!(tx->result == result))
            {
                printf("\r\n# TODO 3 Failed at simtime %ld", sim_time);
                printf("\r\n# TODO 3 INPUT TRACE: in->dividend = 0x%x, in->divisor = 0x%x, in->opn_valid = 0x%x, in->res_ready = 0x%x, in->sign = 0x%x", in->dividend, in->divisor, in->opn_valid, in->res_ready, in->sign);
                printf("\r\n# TODO 3 OUTPUT TRACE: tx->res_valid = 0x%x, tx->result = 0x%x", tx->res_valid, tx->result);
                printf("\r\n# TODO 3 OUTPUT TRACE: remainder = 0x%x, quotient = 0x%x", remainer, quotient);
                printf("\r\n");
                fflush(stdout);

                myexit(tx->result == result, "TODO 3 Failed: Division logic result of the Verilog module is incorrect when res_valid is on")
            }
        }

        /* TODO END 3 */

        delete in;
        delete tx;
    }
};

class div_8bitInDrv
{
private:
    Vdiv_8bit *dut;

public:
    div_8bitInDrv(Vdiv_8bit *dut)
    {
        this->dut = dut;
    }

    void drive(div_8bitInTx *tx)
    {
        /* TODO BEGIN 4 */
        if (tx != NULL)
        {
            dut->dividend = tx->dividend;
            dut->divisor = tx->divisor;
            dut->opn_valid = tx->opn_valid;
            dut->res_ready = tx->res_ready;
            dut->rst = tx->rst;
            dut->sign = tx->sign;
            delete tx;
        }
        /* TODO END 4 */

        dut->eval();
    }
};

