    {
        div_8bitInTx *tx = new div_8bitInTx();

        /* TODO BEGIN 5 */
        tx->dividend = dut->dividend;
        tx->divisor = dut->divisor;
        tx->opn_valid = dut->opn_valid;
        tx->res_ready = dut->res_ready;
        tx->rst = dut->rst;
